SOURCE='"""Server READ ONLY follow-up for one Q04-post-command-validation result.\n\nInput contains no credentials. Does not mutate the input or database. Emits only\nQA IDs/counts/states, never command payloads or unrelated rows.\n"""\nimport argparse\nimport datetime\nimport json\nimport pathlib\nimport re\nimport subprocess\nimport uuid\n\nDEVICE = \'c13ad287-76b1-38cd-b16e-946b37e8c88e\'\nNAMES = [\'missing\', \'wrong_bool\', \'unknown_param\', \'unknown_command\', \'wrong_enum\']\n\n\ndef sql_for(result):\n    run = result[\'run_id\']\n    if not re.fullmatch(r\'q04validate-[0-9a-f]{32}\', run) or result[\'device_id\'] != DEVICE:\n        raise ValueError(\'not the approved QA fixture/run\')\n    mid = str(uuid.UUID(result[\'legal\'][\'message_id\']))\n    if mid != result[\'legal\'][\'message_id\'] or result[\'legal\'][\'key\'] != run + \'-legal\':\n        raise ValueError(\'invalid accepted command identity\')\n    if [case[\'key\'] for case in result[\'cases\']] != [run + \'-\' + name for name in NAMES]:\n        raise ValueError(\'incomplete or changed negative matrix\')\n    start = datetime.datetime.fromisoformat(result[\'started_at\'])\n    end = datetime.datetime.fromisoformat(result[\'finished_at\'])\n    if start.tzinfo is None or end.tzinfo is None or not 0 < (end-start).total_seconds() < 180:\n        raise ValueError(\'unexpected acceptance window\')\n    keys = \',\'.join("\'{}-{}\'".format(run, name) for name in NAMES)\n    return """BEGIN READ ONLY;\nSET LOCAL statement_timeout=\'5s\';\nSELECT json_build_object(\n \'negative_admissions\',(SELECT count(*) FROM broker_command_requests WHERE device_id=\'{device}\' AND idempotency_key IN ({keys})),\n \'positive\',(SELECT coalesce(json_agg(json_build_object(\'id\',id,\'state\',state,\'device_id\',device_id)), \'[]\'::json) FROM broker_command_requests WHERE device_id=\'{device}\' AND idempotency_key=\'{run}-legal\'),\n \'positive_logs\',(SELECT count(*) FROM command_set_logs WHERE device_id=\'{device}\' AND message_id=\'{mid}\'),\n \'other_logs_in_window\',(SELECT count(*) FROM command_set_logs WHERE device_id=\'{device}\' AND created_at >= \'{start}\'::timestamptz AND created_at <= \'{end}\'::timestamptz AND message_id IS DISTINCT FROM \'{mid}\'));\nCOMMIT;""".format(device=DEVICE, keys=keys, run=run, mid=mid, start=start.isoformat(), end=end.isoformat())\n\n\ndef assess(result, audit):\n    return (result.get(\'status\') == \'AWAITING_STORE_AUDIT\'\n            and result.get(\'api_wire_pass\') is True\n            and result.get(\'cleanup\', {}).get(\'restored_false\') is True\n            and result.get(\'cleanup\', {}).get(\'all_connections_closed\') is True\n            and all(case.get(\'rejected\') and case.get(\'no_log\') and case.get(\'frame_count\') == 0\n                    for case in result[\'cases\'])\n            and audit.get(\'negative_admissions\') == 0 and audit.get(\'positive_logs\') == 1\n            and audit.get(\'other_logs_in_window\') == 0\n            and audit.get(\'positive\') == [{\'id\': result[\'legal\'][\'message_id\'],\n                                          \'state\': \'device_reported_success\', \'device_id\': DEVICE}])\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'result\', type=pathlib.Path)\n    args = parser.parse_args()\n    result = json.loads(args.result.read_text(encoding=\'utf-8\'))\n    query = sql_for(result)\n    process = subprocess.run([\'docker\', \'exec\', \'-i\', \'timescaledb\', \'psql\', \'-X\', \'-q\', \'-At\',\n        \'-v\', \'ON_ERROR_STOP=1\', \'-U\', \'postgres\', \'-d\', \'ThingsPanel\'], input=query.encode(),\n        stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=12)\n    if process.returncode:\n        raise SystemExit(\'READ_ONLY_AUDIT_FAILED\')\n    lines = [line for line in process.stdout.decode().splitlines() if line.strip()]\n    if len(lines) != 1:\n        raise SystemExit(\'UNEXPECTED_AUDIT_ROWS\')\n    audit = json.loads(lines[0])\n    passed = assess(result, audit)\n    print(json.dumps({\'run_id\': result[\'run_id\'], \'device_id\': DEVICE, \'pass\': passed,\n                      \'readonly\': True, \'audit\': audit}))\n    raise SystemExit(0 if passed else 1)\n'
